function icon(string $name, int $size = 20, string $class = ''): string {
    $paths = icon_paths();
    if (!isset($paths[$name])) return '';
    $cls = 'i' . ($class !== '' ? ' ' . $class : '');
    return '<svg class="' . $cls . '" width="' . $size . '" height="' . $size . '" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">' . $paths[$name] . '</svg>';
}
